/**
 * Copy for the approved homepage. German source strings are the stable keys.
 * Keep service IDs, DOM IDs, routes, company names and contact details unchanged.
 * Interpolation is plain text: callers must not turn translations into HTML.
 */
export type HomeLanguage = 'de' | 'en' | 'es' | 'pt' | 'it' | 'fr';
export type HomeTextParams = Readonly<Record<string, string | number>>;

export const homeLanguages = [
  { code: 'de', label: 'Deutsch', flag: '🇨🇭', locale: 'de-CH' },
  { code: 'en', label: 'English', flag: '🇬🇧', locale: 'en-GB' },
  { code: 'es', label: 'Español', flag: '🇪🇸', locale: 'es-ES' },
  { code: 'pt', label: 'Português', flag: '🇵🇹', locale: 'pt-PT' },
  { code: 'it', label: 'Italiano', flag: '🇮🇹', locale: 'it-IT' },
  { code: 'fr', label: 'Français', flag: '🇫🇷', locale: 'fr-FR' },
] as const satisfies readonly { code: HomeLanguage; label: string; flag: string; locale: string }[];

export function normalizeHomeLanguage(language: unknown): HomeLanguage {
  const code = typeof language === 'string' ? language.trim().toLowerCase().replace(/_/g, '-').split('-')[0] : '';
  return homeLanguages.some(option => option.code === code) ? code as HomeLanguage : 'de';
}

