export type HomeTranslationSource = typeof rows[number][0];
export type HomeDictionary = Readonly<Record<HomeTranslationSource, string>>;
export const homeTranslationSources: readonly HomeTranslationSource[] = Object.freeze(rows.map(row => row[0]));

export const homeTranslations = Object.freeze(Object.fromEntries(
  homeLanguages.map((language, index) => [
    language.code,
    Object.freeze(Object.fromEntries(rows.map(row => [row[0], row[index]]))),
  ]),
)) as Readonly<Record<HomeLanguage, HomeDictionary>>;

/** German-source lookup; regional language aliases use the same six dictionaries. */
export function homeText(language: unknown, source: HomeTranslationSource | (string & {}), params?: HomeTextParams): string {
  const key = source.replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
  const dictionary = homeTranslations[normalizeHomeLanguage(language)];
  const translation = Object.prototype.hasOwnProperty.call(dictionary, key)
    ? dictionary[key as HomeTranslationSource]
    : key;
  const result = translation.replace(/\{([A-Za-z][A-Za-z0-9_]*)\}/g, (placeholder, name: string) =>
    params && Object.prototype.hasOwnProperty.call(params, name) ? String(params[name]) : placeholder);
  // Runtime sentence fragments sometimes deliberately carry a boundary space.
  return (/^\s/.test(source) ? ' ' : '') + result + (/\s$/.test(source) ? ' ' : '');
}
